import sys

def transform(A, B):
    if len(A) != len(B):
        return -1
    count = [0] * 256
    for i in range(len(A)):
        count[ord(A[i])] += 1
        count[ord(B[i])] -= 1
    for i in range(256):
        if count[i] != 0:
            return -1
    result = 0
    i = len(A) - 1
    j = len(B) - 1
    while i >= 0:
        if A[i] == B[j]:
            j -= 1
        else:
            result += 1
        i -= 1
    return result

input = sys.stdin.read().strip().split()
A = input[0]
B = input[1]
print(transform(A, B))
